package main

const jsReceipts = `
const outcomeLabels={SUCCESS:"成功",CANCELLED:"已停止",INTERRUPTED:"重啟中斷",RUNNING:"處理中",RATE_LIMITED:"超出速率限制",NETWORK:"連線失敗",TIMEOUT:"逾時",PARSER:"回應格式有誤",AUTH_INVALID:"認證失敗"};
const receiptReasons={NO_PRICING_SNAPSHOT:"沒有當次有效標價",TOKEN_USAGE_UNKNOWN:"站方未提供完整 Token 用量",TOKEN_PRICE_UNKNOWN:"Token 單價尚未確認",FIXED_CHARGE_UNKNOWN:"固定費用尚未確認",USAGE_BASIS_UNKNOWN:"此協定的計費用量定義尚未確認",CACHE_USAGE_UNKNOWN:"快取用量未提供",CACHE_READ_PRICE_UNKNOWN:"快取讀取單價未提供",CACHE_WRITE_PRICE_UNKNOWN:"快取寫入單價未確認",CACHE_USAGE_INVALID:"站方快取計數不一致",REQUEST_NOT_COMPLETED:"請求未完成，保留未知",INVALID_PRICE:"標價格式有誤",REQUEST_NOT_FINISHED:"請求尚未完成"};
function tokenValue(v){return v===null||v===undefined?"未知":String(v);}
function usdValue(v){if(v===null||v===undefined)return "未知";const n=Number(v);if(n>0&&n<1e-8)return "< USD 0.00000001";return "USD "+String(v);}
function requestLink(target,id,label="請求詳情"){if(id)action(target,label,()=>requestDetail(id));}
async function requestDetail(id){const view=requestReceiptSurface(),box=view.box;try{const r=await api("/telemetry/detail?id="+encodeURIComponent(id));if(!view.current())return;view.heading.textContent=outcomeLabels[r.outcome]||r.outcome;box.append(el("p",r.model_id+" · "+(providers.find(p=>p.id===r.provider_id)?.name||r.provider_id)+" / "+connectionLabel(r),"media-hint"),el("p",new Date(r.created_at).toLocaleString()+" · "+(operationLabels[r.operation]||r.operation)+" · Key 版本 "+r.credential_version,"media-hint"));const stats=el("div",undefined,"metrics"),d=r.details||{},receipt=d.receipt;box.append(stats);for(const [label,value]of [["輸入 Token",tokenValue(r.input_tokens)],["輸出 Token",tokenValue(r.output_tokens)],["快取讀取",tokenValue(d.cache_read_tokens)],["快取寫入",tokenValue(d.cache_write_tokens)],["推理 Token",tokenValue(d.reasoning_tokens)],["總 Token",tokenValue(d.total_tokens)],["TTFT",r.ttft_ms===null?"未知":r.ttft_ms+" ms"],["總時間",r.latency_ms===null?"未知":r.latency_ms+" ms"]])item(stats,label,value);
 if(receipt){const cost=receipt.cost||{};box.append(el("h3","當次費用"));item(box,"站方回報扣款",usdValue(cost.actual));item(box,"標價估算",usdValue(cost.nominal_estimated));if(cost.estimated!==null)item(box,"已確認 Key 費率的估算",usdValue(cost.estimated));if(cost.nominal_estimated===null)box.append(el("p",receiptReasons[cost.reason]||"資料尚未確認","media-hint"));if(cost.reported_charge?.unit==="UNKNOWN")item(box,"站方回報（單位未確認）",tokenValue(cost.reported_charge.amount));box.append(el("p","標價估算依請求前保存的單價；與實際扣款分開。","media-hint"));if(receipt.pricing_snapshot){const p=receipt.pricing_snapshot;factsView(box,"當次價格 · "+p.source+" · "+new Date(p.observed_at).toLocaleString(),p);}else box.append(el("p","當次價格來源未知","media-hint"));for(const [title,pools]of [["請求前額度",receipt.quota_before],["請求後保存的額度",receipt.quota_after]]){const section=el("details");section.append(el("summary",title));if(!pools?.length)section.append(el("p","尚無有效資料"));(pools||[]).forEach(p=>{const pool=el("div",undefined,"item");pool.append(el("strong",p.facts?.scope_kind||p.kind),el("small",p.source+" · "+new Date(p.observed_at).toLocaleString()));factsView(pool,"額度數值與單位",p);section.append(pool);});box.append(section);}factsView(box,"此回應的速率限制（與資源池分開）",receipt.response_quota||{});}else box.append(el("p","這筆舊紀錄尚無當次價格快照。","media-hint"));const actions=el("div",undefined,"actions");box.append(actions);action(actions,"重新讀取",()=>requestDetail(id));const download=el("a","下載這筆紀錄","link-button");download.href="/api/v1/telemetry/detail?id="+encodeURIComponent(id);download.download="modelatlas-request-"+id+".json";actions.append(download);if(r.retry_of)requestLink(actions,r.retry_of,"上一次請求");
 if(r.source==="PLAYGROUND"&&r.session_id&&!["SUCCESS","RUNNING"].includes(r.outcome)&&myModels.some(m=>key(m)===key(r)&&m.state==="ACTIVE"&&m.enabled)){action(actions,"用目前設定重試",async()=>{if(busy)throw Error("請先等待目前請求完成");rememberComposerDraft();fileReadVersion++;const changed=$("target").value!==key(r);$("target").value=key(r);if(changed)prepareComposerSelection();updatePlayground();await sessionSelectRefresh(r.session_id);restoreComposerDraft();await loadChat();$("request-receipt").close();$("detail").close();show("playground");workspace("playground","work-chat");await sendChat([],r.id);});}
 factsView(box,"Scope 與完整紀錄",r);
 }catch(e){if(view.current())detailState(box,e.message,true,()=>requestDetail(id));}}
async function requestHistory(options={}){const box=modal(options.session?"這段對話的請求":"請求紀錄"),ticket=detailVersion;return renderRequestHistory(box,options,()=>detailCurrent(ticket));}
async function renderRequestHistory(box,{selection=null,session=null}={},isCurrent=()=>true){const toolbar=el("div",undefined,"toolbar"),search=field(toolbar,"搜尋請求","search"),state=el("select"),label=el("label","請求狀態");state.setAttribute("aria-label","請求狀態");for(const [value,text]of [["","全部"],["SUCCESS","成功"],["RATE_LIMITED","速率限制"],["NETWORK","連線失敗"],["CANCELLED","已停止"],["INTERRUPTED","重啟中斷"]])option(state,value,text);label.append(state);toolbar.append(label);box.append(toolbar);const download=el("a","下載篩選後的全部紀錄","link-button"),rowsBox=el("div",undefined,"cards request-list"),more=el("button","顯示更多請求","ghost");more.type="button";box.append(download,rowsBox,more);let offset=0,timer,requestHistoryVersion=0;
 const args=()=>{const p=new URLSearchParams({q:search.value,outcome:state.value});if(selection)for(const [k,v]of new URLSearchParams(query(selection)))p.set(k,v);if(session)p.set("session_id",session);return p;};
 const load=async(append=false)=>{const version=++requestHistoryVersion;if(!append){offset=0;rowsBox.replaceChildren();}const p=args();download.href="/api/v1/telemetry/export?"+p;download.download="";p.set("limit","50");p.set("offset",String(offset));more.disabled=true;try{const rows=await api("/telemetry?"+p);if(version!==requestHistoryVersion||!isCurrent())return;rows.forEach(r=>item(rowsBox,r.model_id+" · "+(outcomeLabels[r.outcome]||r.outcome),(providers.find(p=>p.id===r.provider_id)?.name||r.provider_id)+" / "+connectionLabel(r)+" · "+(r.latency_ms===null?"—":r.latency_ms+" ms")+" · "+new Date(r.created_at).toLocaleString(),()=>requestDetail(r.id)));offset+=rows.length;if(!offset)item(rowsBox,"沒有符合的請求","換個篩選條件再看看。");more.hidden=rows.length<50;}catch(e){notice(e.message,true);}finally{more.disabled=false;}};search.addEventListener("input",()=>{requestHistoryVersion++;clearTimeout(timer);timer=setTimeout(()=>load(),250);});state.addEventListener("change",()=>load());more.addEventListener("click",()=>load(true));box.requestHistoryReload=load;await load();}
let requestHistoryVersion=0;
function bindReceipts(){$("request-history").addEventListener("click",()=>requestHistory());$("conversation-requests").addEventListener("click",()=>requestHistory({session:$("session").value||null}));}
`
